for n in range(2, 21):
    is_solution = True

    # Test all k such that 1 <= k < n and gcd(k, n) = 1
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 - 1 is a multiple of n
            if (k**2 - 1) % n != 0:
                is_solution = False
                break

    if is_solution:
        passing_candidates.append(n)

print("Passing candidates n:", passing_candidates)

