def check_mod(n):
    coprimes = [k for k in range(1, n) if gcd(k, n) == 1]
    all_satisfied = True
    print(f"Testing n={n}. Coprimes: {coprimes}")
    for k in coprimes:
        k_squared_mod_n = (k * k) % n
        if k_squared_mod_n != 1:
            print(f"Counterexample found: k={k}. k^2 = {k*k}, {k*k}%{n} = {k_squared_mod_n}. Fails.")
            all_satisfied = False
        else:
            print(f"k={k} satisfies the condition.")
    if all_satisfied:
        print(f"Verification successful for n={n}: k^2 === 1 (mod {n}) for all coprime k.")
    else:
        print(f"Verification failed for n={n}.")

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Test n=24
check_mod(24)

