def check_mod_18(n=18):
    coprimes = [k for k in range(1, n) if gcd(k, n) == 1]
    counterexample_found = False
    print(f"\nTesting n={n}. Coprimes: {coprimes}")
    for k in coprimes:
        k_squared_mod_n = (k * k) % n
        if k_squared_mod_n != 1:
            print(f"Counterexample found: k={k}. k^2 = {k*k}, {k*k}%{n} = {k_squared_mod_n}. Fails.")
            counterexample_found = True
            # We only need to find one, so we can break early
            break
        else:
            print(f"k={k} satisfies the condition.")
    if counterexample_found:
        print(f"Verification successful for n={n}: At least one k exists such that k^2 !== 1 (mod {n}).")
    else:
        print(f"Verification failed for n={n}: All coprime k satisfy k^2 === 1 (mod {n}).")

# Test n=18
check_mod_18()
